# TASK: instalar dashboard.py v2 (alertas veraces + dictamen brain + ledger depositos)
import base64,hashlib,json,os,py_compile,re,subprocess,time,urllib.request
B="/home/opc/bot_semillas"
SRC_B64=""
def scrub(s):
    if not s: return s
    s=re.sub(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+|sk-ant-[A-Za-z0-9_\\-]+)","<TOK>",s)
    return re.sub(r"[A-Za-z0-9]{56,}","<REDACTED>",s)
tok=""
try:
    for L in open(B+"/.env"):
        m=re.search(r"(github_pat_[A-Za-z0-9_]+|gh[posru]_[A-Za-z0-9]+)",L)
        if m: tok=m.group(1)
except Exception: pass
info={"task":"install_dashboard_v2","now":time.strftime("%Y-%m-%d %H:%M:%SZ",time.gmtime()),"pasos":[]}
def step(s): info["pasos"].append(s); print("[dashv2]",s)
try:
    src=base64.b64decode(SRC_B64)
    info["sha256"]=hashlib.sha256(src).hexdigest()[:16]
    tmp=B+"/_new_dashboard.py"
    open(tmp,"wb").write(src)
    py_compile.compile(tmp,doraise=True)
    step("compile OK (%d bytes)"%len(src))
    tgt=B+"/dashboard.py"; bak=B+"/dashboard.py.bak.pre_alertas"
    if os.path.exists(tgt) and not os.path.exists(bak):
        open(bak,"wb").write(open(tgt,"rb").read()); step("backup -> .bak.pre_alertas")
    os.replace(tmp,tgt); step("instalado")
    test=("import sys; sys.path.insert(0,'"+B+"'); import dashboard as D;"
          "p=D.build_payload();"
          "assert 'garden_plan_pub' in p, 'falta garden_plan_pub';"
          "assert 'deposits_ledger' in p, 'falta deposits_ledger';"
          "assert isinstance(p['alertas'], list);"
          "print('payload_ok alertas', len(p['alertas']), 'seeded', p['deposits_ledger'].get('seeded'));"
          "print('ALERTAS:', [a['texto'][:80] for a in p['alertas']]);"
          "print('update:', D.update())")
    r=subprocess.run([B+"/venv/bin/python","-c",test],capture_output=True,text=True,timeout=300,cwd=B)
    info["test_stdout"]=scrub(r.stdout[-800:]); info["test_stderr"]=scrub(r.stderr[-500:])
    step("test rc=%d"%r.returncode)
    info["ok"]=(r.returncode==0)
    if r.returncode!=0 and os.path.exists(bak):
        open(tgt,"wb").write(open(bak,"rb").read()); step("ROLLBACK a backup")
except Exception as e:
    info["ok"]=False; info["error"]=scrub(str(e)[:300])
U="https://api.github.com/repos/calcagnoagustin/radar/contents/docs/_diag.json"
def R(m,d=None):
    q=urllib.request.Request(U,data=d,method=m); q.add_header("Authorization","token "+tok); q.add_header("User-Agent","dashv2")
    return urllib.request.urlopen(q,timeout=30).read()
sha=None
try: sha=json.loads(R("GET")).get("sha")
except Exception: pass
p={"message":"install dashboard v2","content":base64.b64encode(json.dumps(info,indent=1).encode()).decode()}
if sha: p["sha"]=sha
try: R("PUT",json.dumps(p).encode()); print("REPORTADO ok=%s"%info.get("ok"))
except Exception as e: print("PUSH_ERR",e)
